import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Profile = () => {
  const { 
    user, 
    logout, 
    cart, 
    removeFromCart, 
    favorites, 
    removeFromFavorites, 
    orders, 
    createOrder, 
    cancelOrder 
  } = useAuth();

  const navigate = useNavigate();
  const location = useLocation();
  const [activeTab, setActiveTab] = useState('profile');
  const [checkoutData, setCheckoutData] = useState({
    cardNumber: '',
    address: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // ✅ Диагностика - что в объекте пользователя
  useEffect(() => {
    if (user) {
      console.log('🔍 User object:', user);
      console.log('🔍 User keys:', Object.keys(user));
      console.log('🔍 User values:', Object.values(user));
    }
  }, [user]);

  // ✅ Функция для безопасного получения имени пользователя
  const getUsername = () => {
    if (!user) return 'Пользователь';

    // Пробуем разные возможные поля
    return user.username || user.name || user.displayName || user.email?.split('@')[0] || 'Пользователь';
  };

  // ✅ Функция для безопасного получения email
  const getUserEmail = () => {
    if (!user) return 'Не указан';
    return user.email || user.mail || 'Не указан';
  };

  // ✅ Обработка параметров таба из URL
  useEffect(() => {
    const searchParams = new URLSearchParams(location.search);
    const tab = searchParams.get('tab');

    if (tab && ['cart', 'favorites', 'orders'].includes(tab)) {
      setActiveTab(tab);
    } else {
      setActiveTab('profile');
    }
  }, [location.search]);

  // ✅ Функция для смены таба
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    if (tab === 'profile') {
      navigate('/profile');
    } else {
      navigate(`/profile?tab=${tab}`);
    }
  };

  // ✅ Функция навигации в каталог
  const goToCatalog = () => {
    navigate('/catalog');
  };

  // ✅ Функция для перехода к товару
  const goToProduct = (productId) => {
    navigate(`/product/${productId}`);
  };

  // ✅ Функция для безопасного получения изображения
  const getProductImage = (product) => {
    if (!product || !product.images || product.images.length === 0) {
      return '/images/placeholder.jpg';
    }
    return product.images[0];
  };

  // ✅ Функция оформления заказа
  const handleCheckout = async (e) => {
    e.preventDefault();
    if (cart.length === 0) {
      alert('Корзина пуста!');
      return;
    }

    setIsSubmitting(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));

      const order = createOrder(checkoutData);

      setCheckoutData({
        cardNumber: '',
        address: ''
      });

      alert(`Заказ #${order.id} успешно оформлен!`);
      handleTabChange('orders');

    } catch (error) {
      alert('Произошла ошибка при оформлении заказа');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ✅ Функция отмены заказа
  const handleCancelOrder = (orderId) => {
    if (window.confirm('Вы уверены, что хотите отменить этот заказ?')) {
      cancelOrder(orderId);
      alert('Заказ отменен');
    }
  };

  // ✅ Функция для получения статуса заказа
  const getOrderStatus = (status) => {
    const statuses = {
      pending: { text: 'В обработке', color: 'text-yellow-600', bg: 'bg-yellow-100' },
      completed: { text: 'Завершен', color: 'text-green-600', bg: 'bg-green-100' },
      cancelled: { text: 'Отменен', color: 'text-red-600', bg: 'bg-red-100' }
    };
    return statuses[status] || statuses.pending;
  };

  if (!user) {
    return (
      <div className="max-w-md mx-auto mt-16 p-8 text-center">
        <p className="text-lg mb-4">Пожалуйста, войдите в систему</p>
        <button 
          onClick={goToCatalog}
          className="bg-gold-600 text-white px-6 py-3 rounded hover:bg-gold-700"
        >
          Войти / Зарегистрироваться
        </button>
      </div>
    );
  }

  const totalPrice = cart.reduce((sum, item) => sum + (item.price * (item.quantity || 1)), 0);

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      <h1 className="text-3xl font-serif font-bold mb-8">Личный кабинет</h1>

      {/* Tabs */}
      <div className="border-b mb-8">
        <div className="flex space-x-8">
          {['profile', 'cart', 'favorites', 'orders'].map(tab => (
            <button
              key={tab}
              onClick={() => handleTabChange(tab)}
              className={`pb-4 px-2 capitalize ${
                activeTab === tab 
                  ? 'border-b-2 border-gold-600 text-gold-600 font-semibold' 
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              {tab === 'profile' ? 'Профиль' : 
               tab === 'cart' ? 'Корзина' : 
               tab === 'favorites' ? 'Понравилось' : 'Мои заказы'}
            </button>
          ))}
        </div>
      </div>

      {/* Profile Tab */}
      {activeTab === 'profile' && (
        <div className="max-w-2xl">
          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-xl font-semibold mb-4">Информация о профиле</h2>
            <div className="space-y-3">
              {/* ✅ ИСПРАВЛЕНО: используем безопасные функции */}
              <p><strong>Имя пользователя:</strong> {getUsername()}</p>
              <p><strong>Email:</strong> {getUserEmail()}</p>

              {/* Дополнительная информация */}
              <p><strong>Количество заказов:</strong> {orders?.length || 0}</p>
              <p><strong>Товаров в избранном:</strong> {favorites?.length || 0}</p>
              <p><strong>Товаров в корзине:</strong> {cart?.length || 0}</p>
            </div>

            {/* Отладочная информация - покажет какие поля есть в объекте пользователя */}
            <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded">
              <p className="text-yellow-800 font-medium mb-2">Отладочная информация:</p>
              <p className="text-yellow-700 text-sm">
                Доступные поля пользователя: <strong>{Object.keys(user).join(', ') || 'нет полей'}</strong>
              </p>
            </div>

            <button
              onClick={() => {
                logout();
                navigate('/');
              }}
              className="mt-6 bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded"
            >
              Выйти
            </button>
          </div>
        </div>
      )}

      {/* Cart Tab */}
      {activeTab === 'cart' && (
        <div>
          {cart.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-xl text-gray-500 mb-4">Корзина пуста</p>
              <button 
                onClick={goToCatalog}
                className="bg-gold-600 text-white px-6 py-3 rounded hover:bg-gold-700"
              >
                Перейти к покупкам
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Cart Items */}
              <div className="lg:col-span-2">
                <h2 className="text-xl font-semibold mb-4">Товары в корзине</h2>
                <div className="space-y-4">
                  {cart.map(item => (
                    <div key={item.id} className="flex items-center bg-white rounded-lg shadow-md p-4">
                      <img 
                        src={getProductImage(item)}
                        alt={item.name}
                        className="w-20 h-20 object-cover rounded cursor-pointer"
                        onClick={() => goToProduct(item.id)}
                      />
                      <div className="ml-4 flex-grow">
                        <h3 
                          className="font-semibold cursor-pointer hover:text-gold-600"
                          onClick={() => goToProduct(item.id)}
                        >
                          {item.name}
                        </h3>
                        <p className="text-gold-600 font-bold">{item.price?.toLocaleString()} ₽</p>
                        <p className="text-gray-500 text-sm">Количество: {item.quantity || 1}</p>
                      </div>
                      <button
                        onClick={() => removeFromCart(item.id)}
                        className="text-red-500 hover:text-red-700 ml-4 p-2"
                      >
                        ✕ Удалить
                      </button>
                    </div>
                  ))}
                </div>
              </div>

              {/* Checkout Form */}
              <div className="bg-white rounded-lg shadow-md p-6 h-fit">
                <h2 className="text-xl font-semibold mb-4">Оформление заказа</h2>
                <form onSubmit={handleCheckout}>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium mb-2">Номер карты</label>
                      <input
                        type="text"
                        placeholder="1234 5678 9012 3456"
                        value={checkoutData.cardNumber}
                        onChange={(e) => setCheckoutData({...checkoutData, cardNumber: e.target.value})}
                        className="w-full px-3 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-gold-500"
                        required
                        maxLength="19"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium mb-2">Адрес доставки</label>
                      <textarea
                        placeholder="Введите полный адрес доставки"
                        value={checkoutData.address}
                        onChange={(e) => setCheckoutData({...checkoutData, address: e.target.value})}
                        className="w-full px-3 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-gold-500"
                        rows="3"
                        required
                      />
                    </div>
                    <div className="border-t pt-4">
                      <div className="flex justify-between text-lg font-semibold">
                        <span>Итого:</span>
                        <span>{totalPrice.toLocaleString()} ₽</span>
                      </div>
                    </div>
                    <button
                      type="submit"
                      disabled={isSubmitting || cart.length === 0}
                      className={`w-full py-3 rounded-lg font-semibold transition-all ${
                        isSubmitting || cart.length === 0
                          ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                          : 'bg-gold-600 hover:bg-gold-700 text-white shadow-lg hover:shadow-xl'
                      }`}
                    >
                      {isSubmitting ? 'ОФОРМЛЕНИЕ...' : 'ОФОРМИТЬ ЗАКАЗ'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Остальные вкладки остаются без изменений */}
      {/* ... */}
    </div>
  );
};

export default Profile;
